--
-- 資料表結構 `daily_report`
--

CREATE TABLE `daily_report` (
  `id` int(11) NOT NULL,
  `report_date` date NOT NULL COMMENT '報表日期',
  `weekday` varchar(10) NOT NULL COMMENT '星期幾',
  `filled_by` text NOT NULL COMMENT '填表人',
  `cash_income` int(11) NOT NULL COMMENT '現金收入',
  `linepay_income` int(11) NOT NULL COMMENT 'Line Pay 收入',
  `uber_income` int(11) NOT NULL COMMENT 'Uber Eats 收入',
  `other_income` int(11) NOT NULL COMMENT '其他收入',
  `total_income` int(11) NOT NULL COMMENT '收入合計',
  `total_expense` int(11) NOT NULL COMMENT '支出合計',
  `cash_1000` int(11) NOT NULL COMMENT '店內現金 1000 張數',
  `cash_500` int(11) NOT NULL COMMENT '店內現金 500 張數',
  `cash_100` int(11) NOT NULL COMMENT '店內現金 100 張數',
  `cash_50` int(11) NOT NULL COMMENT '店內現金 50 枚數',
  `cash_10` int(11) NOT NULL COMMENT '店內現金 10 枚數',
  `cash_5` int(11) NOT NULL COMMENT '店內現金 5 枚數',
  `cash_1` int(11) NOT NULL COMMENT '店內現金 1 枚數',
  `cash_total` int(11) NOT NULL COMMENT '店內現金總額（可自動計）',
  `deposit_to_bank` int(11) NOT NULL COMMENT '當日存入銀行金額',
  `created_at` datetime NOT NULL COMMENT '建立時間',
  `expense_food` int(11) DEFAULT 0 COMMENT '食材成本',
  `expense_salary` int(11) DEFAULT 0 COMMENT '人事成本',
  `expense_utilities` int(11) DEFAULT 0 COMMENT '水電瓦斯費',
  `utilities_month` varchar(10) NOT NULL,
  `expense_delivery` int(11) DEFAULT 0 COMMENT '外送平台抽成',
  `expense_misc` int(11) DEFAULT 0 COMMENT '雜項支出',
  `expense_rent` int(11) DEFAULT 0 COMMENT '租金',
  `enable_utilities` tinyint(1) DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

