--
-- 觸發器 `daily_report`
--
DELIMITER $$
CREATE TRIGGER `daily_report_before_insert` BEFORE INSERT ON `daily_report` FOR EACH ROW BEGIN
    SET NEW.total_expense = 
        COALESCE(NEW.expense_salary,0) +
        COALESCE(NEW.expense_utilities,0) +
        COALESCE(NEW.utilities_month,0) +
        COALESCE(NEW.expense_rent,0) +
        COALESCE(NEW.expense_food,0) +
        COALESCE(NEW.expense_delivery,0) +
        COALESCE(NEW.expense_misc,0);
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `daily_report_before_update` BEFORE UPDATE ON `daily_report` FOR EACH ROW BEGIN
    SET NEW.total_expense = 
        COALESCE(NEW.expense_salary,0) +
        COALESCE(NEW.expense_utilities,0) +
        COALESCE(NEW.utilities_month,0) +
        COALESCE(NEW.expense_rent,0) +
        COALESCE(NEW.expense_food,0) +
        COALESCE(NEW.expense_delivery,0) +
        COALESCE(NEW.expense_misc,0);
END
$$
DELIMITER ;

