--
-- 資料表結構 `薪資管理`
--

CREATE TABLE `薪資管理` (
  `id` varchar(20) NOT NULL,
  `name` varchar(50) NOT NULL COMMENT '員工姓名',
  `salary_month` char(7) NOT NULL COMMENT '薪資月份 (YYYY-MM)',
  `base_salary` decimal(10,2) DEFAULT NULL COMMENT '底薪',
  `hourly_rate` decimal(10,2) DEFAULT NULL COMMENT '時薪',
  `working_hours` decimal(10,2) DEFAULT 0.00 COMMENT '工時總數',
  `bonus` decimal(10,2) DEFAULT 0.00 COMMENT '獎金',
  `deductions` decimal(10,2) DEFAULT 0.00 COMMENT '扣款',
  `total_salary` decimal(10,2) GENERATED ALWAYS AS (case when `base_salary` is not null and `base_salary` <> 0 then `base_salary` + `bonus` - `deductions` else ifnull(`hourly_rate`,0) * ifnull(`working_hours`,0) + `bonus` - `deductions` end) STORED COMMENT '實領薪資（自動計算）',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `hours_manual` decimal(6,2) DEFAULT NULL COMMENT '管理員手動輸入工時',
  `att_last_sum` decimal(6,2) DEFAULT NULL COMMENT '打卡表當時的累計快照'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='薪資管理';

